import json
from pathlib import Path
bank=[]
def q(course,topic,pages,prompt,options,correct,rationale):
 bank.append(dict(id=f'{course}-{sum(x["course"]==course for x in bank)+1:02}',course=course,topic=topic,pages=pages,prompt=prompt,options=options,correct=correct,rationale=rationale))
q('OR100','Case and log',[17,22],'A procedure has finished. Which record should describe what actually happened in the operating room?', ['The surgical case','The surgical log','The surgeon preference list','The scheduling block'],[1],'The log records the actual surgical event; the case is the plan. Preference lists organize orders and blocks reserve scheduling time.')
q('OR100','Case and log',[22],'After a log has been created, a planner changes the surgical case. What is the safe expectation?', ['The log automatically receives every change','The log must be reviewed separately; case changes do not automatically copy forward','Posting is required to synchronize the two','The case becomes the record of actual care'],[1],'Once the log exists, later case changes do not automatically update it. Posting concerns charges and log closure, not synchronization.')
q('OR100','Case entry',[30,40],'Which set contains only the five programmatically required case details?', ['Patient, date, surgeon, anesthesia type, location','Patient, location, service, procedure, surgeon','Patient, equipment, date, procedure, service','Surgeon, laterality, patient class, date, location'],[1],'Patient, location, service, procedure, and surgeon are the five required items. Other details may be important or locally required but are not this five-item set.')
q('OR100','Scheduling',[48,63],'A scheduler needs to locate cases that have not yet been placed on the schedule. Where should they begin?', ['Post Charges','Depot','LDA Avatar','Chart Review'],[1],'The Depot holds unscheduled cases. Post Charges supports charge posting; the other activities do not serve as the unscheduled-case queue.')
q('OR100','Scheduling',[51,63],'A patient decides not to undergo a correctly created planned procedure. Which action fits this situation?', ['Void the case as an entry error','Cancel the case','Shuffle the case','Swap it with another case'],[1],'Cancel is appropriate when the planned procedure will not happen. Void is for a case created in error; shuffle and swap rearrange scheduling.')
q('OR100','Scheduling',[63],'A duplicate case was accidentally created. Which action best represents the error?', ['Cancel the intended procedure','Trigger its charges','Void the duplicate case','Post the duplicate log'],[2],'Void identifies a case created in error. Cancel refers to a planned procedure that will not occur; charge actions do not correct duplicate case entry.')
q('OR100','Orders',[41,84],'An authorized order is held for a later phase. What makes that Signed & Held order active?', ['Adding a preference card','Releasing the order','Posting the log','Creating a scheduling block'],[1],'Releasing a Signed & Held order makes it active. Cards, blocks, and posting do not replace release.')
q('OR100','Orders',[41],'Which factors does the course identify for assigning the default signing action to an order? Select all that apply.', ['The intended phase of care','The patient location','The number of preference cards','The inventory manufacturer'],[0,1],'The system uses phase of care and patient location to determine whether an order is for now or later. Card count and manufacturer do not drive this decision.')
q('OR100','Navigators',[83,84],'Before leaving a perioperative phase, a nurse wants to confirm required documentation is complete. Which navigator section is the best fit?', ['Verify','Case Request','Calendar','Resource Sidebar'],[0],'Verify supports confirmation of required documentation. The scheduling and case-request tools serve different workflows.')
q('OR100','Procedure Pass',[71,83],'A nurse wants to focus on pre-surgical tasks assigned to their role. Which approach is most direct?', ['Use the Tasks section grouped by role','Post the log to filter the tasks','Remove the case from the schedule','Open a surgeon preference list'],[0],'Procedure Pass tasks can be grouped by role. Posting, unscheduling, and order preference lists do not provide that task view.')
q('OR100','Preference tools',[40,49,114],'A surgeon wants to place several related orders together during one ordering session. Which tool fits?', ['Order set','Preference card','OR block','Surgical log'],[0],'An order set groups related orders for ordering. A preference card configures surgical preferences; a block reserves time; a log records actual surgery.')
q('OR100','Inventory',[104,105],'Which items belong to the pick-list content described in the course? Select all that apply.', ['Medications','Supplies','Named circulating nurses','Individually assigned equipment'],[0,1],'Pick lists contain medication and inventory needs. Staff and equipment assignments are resource concepts, not those pick-list contents.')
q('OR100','Inventory',[105],'Compared with supply documentation, what additional information is characteristic of implant tracking?', ['Only the number of scheduled cases','Implant action, serial number, and expiration date','Only the surgeon login password','Only the scheduling block owner'],[1],'Implants require additional tracking such as action, serial number, and expiration date. Both supplies and implants can also require used and wasted quantities.')
q('OR100','Flowsheets',[122,123],'A nurse sees device values waiting to be filed. Why should those values be validated?', ['To review accuracy before filing to the chart','To automatically post the surgical log','To create a new preference card','To change the patient service'],[0],'Validation lets the clinician review device values before they enter the chart and avoids filing unnecessary data. It is not a charge-posting or scheduling function.')
q('OR100','Charging',[135,136],'Some charges are ready, but further documentation is expected. Which action can send ready charges while leaving the log open?', ['Post the log','Trigger charges','Void the case','Cancel the surgery'],[1],'Triggering sends eligible charges while keeping the log open. Posting closes the log and later changes require an addendum.')
q('OR100','Reporting',[152],'A team wants a custom list of last month’s logs missing incision closure documentation. Which reporting tool is the course’s best fit?', ['Reporting Workbench','A scheduling block','An order set','A preference card'],[0],'Reporting Workbench supports this custom operational report. Blocks, order sets, and cards are configuration/workflow tools, not the reporting mechanism.')
q('CLN251-252','Data structure',[40,41],'In Chronicles terminology, an office visit within a patient record is best understood as which component?', ['A master file','A contact','An INI','A security point'],[1],'A contact holds data for a particular encounter or time within a record. The master file groups records; a security point grants functionality.')
q('CLN251-252','Data structure',[41],'An analyst finds a wrong value while using Record Viewer. What can they do in that activity?', ['View the value, then use an appropriate editing tool to change it','Edit any item directly','Change the record’s security class by typing over the value','Delete the underlying contact'],[0],'Record Viewer is read-only. Identifying an item there does not make it an editing or deletion tool.')
q('CLN251-252','Reports',[66],'Every user of a shared report needs the same added information. What is the efficient approach described by the course?', ['Always create one report per user','Edit the existing shared report when appropriate','Replace every print group with a role','Create a new provider record'],[1],'When all consumers need a change, editing the shared record avoids unnecessary copies. Roles and providers do not replace report build.')
q('CLN251-252','Reports',[66],'What reusable components make up an LRP report?', ['LPG print groups','ECL security points','EMP user templates','ORT charge settings'],[0],'LRP reports are composed of LPG print groups. The other records control security, shared user configuration, and charging.')
q('CLN251-252','Profiles',[106],'A user can enter an activity but sees the wrong options inside it. Which type of configuration is the strongest first lead?', ['Profile','Password policy','Provider referral address','Inventory balance'],[0],'Profiles configure options inside activities. Security controls access; the other options do not configure those activity details.')
q('CLN251-252','Profiles',[77,78,106],'For an ordinary profile item, both department and EMR System Definitions profiles supply a value. Which wins?', ['The department value','The system value','Both values are always appended','Whichever was edited last'],[0],'Department is more specific in the profile hierarchy. Compilation uses specificity, not edit time or automatic merging.')
q('CLN251-252','Profiles',[80,81],'A more-specific profile supplies one entry for an ordinary multiple-response item. A general profile has three entries. What should the builder normally expect?', ['All four entries merge','The more-specific set replaces the general set','The general set always wins','The item becomes blank'],[1],'Ordinary multiple-response items are all-or-nothing at the selected level. Some items have special behavior, so field help matters; automatic merging is not the general rule.')
q('CLN251-252','Profiles',[79],'Where should a builder generally start settings that apply to the widest population?', ['At the most general appropriate level','In a separate user profile for each employee','At whichever record has the newest contact','Only in the provider record'],[0],'Start broad, then configure exceptions at more-specific levels. This reduces duplicate settings and maintenance.')
q('CLN251-252','Workflow Engine',[135],'The Workflow Engine rule selected through a compiled profile does not match an encounter. Does the system automatically try a lower-level profile’s rule?', ['Yes, until every profile is exhausted','No; only the selected compiled-profile rule is used','Yes, but only after posting charges','Only if the user has multiple provider records'],[1],'There is no automatic fallback through other profile-level Workflow Engine rules when conditions do not match.')
q('CLN251-252','Workflow Engine',[135],'A directive executes and has no Continue afterwards setting. What happens to later conditions in that rule?', ['They are not evaluated after that directive','They always all run','They merge into the user role','They become security points'],[0],'Without continuation, rule evaluation stops after executing the directive. Roles and security are unrelated to that control flow.')
q('CLN251-252','Navigators',[152],'Which ordering describes navigator structure from broadest to most specific?', ['Section → topic → template','Template → topic → section','Report → role → section','Profile → security point → contact'],[1],'Navigator templates contain topics, which contain sections. These are different types of LVN records, not different master files.')
q('CLN251-252','Roles',[169],'A user has three startup activities, two patient workspaces, and one preference-list composer open. How many workspaces count in the course example?', ['Six','Five','Four','Three'],[2],'Startup activities collectively count as one workspace. Add the two patient workspaces and the composer: four total.')
q('CLN251-252','Roles and security',[169,182],'Which configuration pairs are correct? Select all that apply.', ['Role: layout and behavior on login','Security class: permitted functionality','Profile: options within activities','Provider record: every user’s startup workspace limit'],[0,1,2],'Roles govern layout/behavior, security grants access, and profiles supply activity details. Workspace limits belong to roles, not provider records.')
q('CLN251-252','Security',[182],'In the course’s security model, which types are identified for every user? Select all that apply.', ['In Basket','Reporting Workbench','Shared','Inpatient'],[0,1,2],'In Basket, Reporting Workbench, and Shared apply to every user in the course model. Inpatient is for hospital clinical tools rather than every user.')
q('CLN251-252','Providers and users',[203,204],'A community physician receives referrals but never logs in to your Epic system. Which record may still be needed?', ['A provider record without a user login','Only a user template','Only a charge profile','A new report for each referral'],[0],'SER can represent a referring or referred-to provider who does not log in. EMP is needed for a login, not simply to exist as a provider.')
q('CLN251-252','Providers and users',[203],'Where should an individual’s provider record be linked?', ['To their individual user record','To a template shared by all clinicians','To the department profile instead of a user','To every report they open'],[0],'Provider identity links to the individual user record. A shared user template should not represent a single provider identity.')
q('CLN251-252','User templates',[203,286],'Which settings are shared through the user template in the course model? Select all that apply.', ['Role','Security classes','Profile','Individual login password'],[0,1,2],'Role, security classes, and profile are common template settings. Individual credentials belong to the individual user.')
q('CLN251-252','Category lists',[226],'A builder needs to open a category list for maintenance. Which identifiers are required?', ['Master-file INI and item number','Screen color and workspace count','Only the category title','Provider ID and password'],[0],'The list is located using its master-file INI and item number. A display title alone is not its item address.')
q('CLN251-252','Category lists',[226],'A category value is obsolete but has been used in production. What maintenance action preserves its historical meaning?', ['Deactivate the value','Delete it and reuse the ID for a new meaning','Rename it to an unrelated concept','Erase all historical contacts'],[0],'Deactivation retires an option while preserving historical use. Reusing or changing the meaning of an existing ID can distort old data.')
q('CLN251-252','Category lists',[226],'Category List Maintenance displays Release Range: All Categories. How should the builder interpret it?', ['Customer-controlled list','Epic-controlled system list that is read-only','Every ID is available for local reuse','The list has no values'],[1],'All Categories indicates an Epic-controlled system list. All Custom, by contrast, is the customer-list designation.')
q('OR350','Definitions',[39,41,43],'For a location setting that inherits normally, no local value is entered but a system value exists. What is used?', ['The system definition value','A random sibling location value','Always a blank value','The user’s most recent case value'],[0],'Location configuration can inherit system definitions when the local item is blank. This is build by exception, not a lookup through other locations.')
q('OR350','Definitions',[47],'A location sets values for Case Creation in the Case Extension form. What happens to system-level values for that same multiple-value item?', ['The local item overrides the system item’s values','All values always merge','The local values are ignored','The system values are deleted from storage'],[0],'The example compiles item by item: a populated local item replaces all system values for that item. It does not delete the stored system configuration.')
q('OR350','Metrics',[65,72,333],'Cases scheduled far apart should be excluded from turnover analysis. Which setting addresses their scheduled separation?', ['Scheduled gap threshold','Supply cost per unit','Procedure Pass lookback','Profile hierarchy level'],[0],'Scheduled gap threshold evaluates the planned gap. Actual turnover thresholds concern measured turnover, not scheduled separation.')
q('OR350','Procedures',[84,85,89],'A new base procedure cannot be found for the intended service and location. Which checks are appropriate? Select all that apply.', ['Its active/inactive setting','Its service authorization','Its location authorization','The surgeon’s preferred screen color'],[0,1,2],'A base procedure must be active and properly authorized for the intended service/location. Screen appearance does not determine this availability.')
q('OR350','Resources',[98,99,334],'A generic equipment requirement and a specific numbered device must both be represented. Which mapping fits?', ['Generic type: ORT; individual device: SER','Generic type: EMP; device: LPG','Both must be user templates','Generic type: IMP; device: LPR'],[0],'ORT describes the resource type; SER represents individually tracked resources. EMP is a user and IMP is implant tracking.')
q('OR350','Resources',[121],'Must every resource type use conflict checking?', ['Yes, without exception','No; conflict checking is optional','Only if it has an EMP password','Only after a log is posted'],[1],'The course explicitly treats conflict checking as optional. It is not made mandatory merely by creating a resource type.')
q('OR350','Operating rooms',[145,334],'A newly built operating room cannot be added to a Snapboard report. Which issues should be checked? Select all that apply.', ['The room is inactive','The room lacks its location link','The room has no blocked time','Its supply item lacks a serial number'],[0,1],'Inactive status and missing location linkage can prevent the room from appearing. Blocking controls available/reserved time, not whether the room can be added to the report.')
q('OR350','Operating rooms',[127,145],'Which pair provides an operating room’s identity and scheduling availability?', ['SER room record and scheduling template','SUP record and user password','IMP record and print group','Category list and role'],[0],'The room is represented by SER; its scheduling template defines availability and blocking. Inventory and user records do not substitute for this pair.')
q('OR350','Inventory',[150,171],'The same supply is stocked in three inventory locations. Which arrangement represents its definition and location-specific balances?', ['One SUP and three BAL records','Three user records and one SUP','One IMP and three roles','One BAL with no SUP'],[0],'SUP stores shared item characteristics; BAL holds location-specific information. IMP is used for implant tracking, not the general item/balance relationship.')
q('OR350','Inventory',[155,156],'An item has a chargeable flag and a code but produces a zero-dollar charge. In the course example, which missing value explains it?', ['Cost per unit','Patient login ID','Navigator caption','Block owner'],[0],'The example lacks cost per unit, so the system cannot calculate the item cost. This is distinct from user, navigator, and block configuration.')
q('OR350','Inventory',[166,169],'Which record tracks information about a particular implant used in surgery?', ['IMP','EMP','LRP','E2R'],[0],'IMP tracks implant documentation/history. EMP is a user, LRP a report, and E2R a role.')
q('OR350','Charging',[208],'A builder needs to define which code is billed every five minutes. Which record is appropriate?', ['Charge code table (OCT)','Navigator topic (LVN)','User template (EMP)','Provider (SER)'],[0],'The charge code table defines the timing code and frequency. Charge settings separately identify the start and end events.')
q('OR350','Charging',[208],'The timing charge should run between In Room and Out of Room. Where are those events selected?', ['Charge settings','Only the EAP charge code','Only the user role','The category list synonym field'],[0],'Charge settings determine the events that bound time-based charges. The table supplies the code/frequency; a code alone does not set these event boundaries.')
q('OR350','Charging',[195,196,208],'Several charge-profile override rules evaluate true. How should the settings be selected?', ['Merge every matching settings record','Use the first matching override in order','Always use the default','Use the last edited record'],[1],'The profile checks overrides in order and uses the first match; otherwise it uses the default. Only one charge settings record applies at a time.')
q('OR350','Charging',[202,203],'A practice table has one base charge for the first 60 minutes and one increment per additional minute. An event lasts 68 minutes. What is generated?', ['One base plus eight increments','Eight bases plus one increment','Sixty-eight base charges','Only one base charge'],[0],'68 minus 60 gives eight additional minutes, so this configured example generates nine charges total. The calculation depends on the stated table, not a universal billing rule.')
q('OR350','Preference cards',[216,217],'Two cards apply: one for this surgeon at this location and one for this surgeon at all locations. Which is more specific?', ['The surgeon-and-location card','The all-locations card','They always merge equally','The one with the longer name'],[0],'Surgeon plus specific location is more specific than the surgeon’s all-locations card. The name length has no priority role.')
q('OR350','Preference cards',[208,216],'Which master file holds both OpTime base procedures and preference cards?', ['ORP','EAP','LPG','EMP'],[0],'ORP holds both base procedures and preference cards. EAP holds procedure/charge codes; LPG and EMP serve other purposes.')
q('OR350','Procedure Pass',[244,245,246],'A task must wait for a lab to be performed and meet result-related criteria, rather than merely find an order. Which task type fits?', ['Procedure & Lab','Presence of Orders','Generic','Appointment'],[0],'Procedure & Lab is suited to completion/results criteria. Presence of Orders can complete from a qualifying order; Generic requires manual completion.')
q('OR350','Procedure Pass',[244,264],'A task should be shown to everyone and be manually completed. Which choices fit? Select all that apply.', ['Use a Generic task for manual completion','No conditional rule is needed solely to make it universal','Use Presence of Orders to force manual completion','Build every task from scratch'],[0,1],'Generic tasks require manual completion, and universal tasks need no conditional rule just to apply to all patients. Reuse suitable existing tasks when possible.')
q('OR350','Documentation',[270,307],'A documentation tool needs complex calculations and concurrent entry by several users. Which tool is generally the better fit in the course comparison?', ['Flowsheets','A report-only print group','A charge code table','A preference-card copy tool'],[0],'Flowsheets support complex calculations and concurrent documentation. SmartForms offer flexible design and scripting; reports and charging tools are not replacements for this documentation need.')
q('OR350','Documentation',[284,307],'Which statements about flowsheet records are correct? Select all that apply.', ['Rows and groups are FLO records','Templates are FLT records','R and G help distinguish rows and groups','Every template must be an EMP record'],[0,1,2],'Rows and groups share FLO and use naming conventions to distinguish them. Templates use FLT; EMP represents users/templates for users.')
q('OR350','Documentation',[276,307],'A SmartForm includes a label that displays instructions but captures no value. Must that label be bound to a Chronicles item?', ['No, non-data components need no storage binding','Yes, every visible component must store data','Yes, but only if a flowsheet exists','Only after charges are triggered'],[0],'Only components that capture data need a storage binding. A label can display information without a data item.')
q('OR350','Security',[315,323,329],'A user logs into one department but opens a case scheduled at a Procedural location. What determines the OpTime security model for that case?', ['The case location’s type','The login department alone','The last provider record edited','The number of open reports'],[0],'The case location type selects Procedural versus OpTime System/Location security. The login department is not the deciding factor.')
q('OR350','Security',[319,322,323],'For a case at a Surgical location with a location-specific security override, which combination applies?', ['System class plus that location’s override class','All assigned location classes merged','Only the override, with no System class','Only the default location class'],[0],'One System class combines with one applicable Location class. A location override replaces the default Location class for that case, not the System class.')
assert len(bank)==60
Path(__file__).with_name('questions.js').write_text('/* Original practice questions; source references are PDF page numbers. */\nwindow.QUESTION_BANK = '+json.dumps(bank,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
print('Built',len(bank),'questions:',{c:sum(q['course']==c for q in bank) for c in ['OR100','OR350','CLN251-252']})
